-- =====================================================================
-- NF Live - New Frontiers keep / component / position / hookpoint data
-- =====================================================================
-- AUTO-GENERATED by scripts/build_nf_live_sql.py from the Eve-of-Darkness
-- vanilla DOL database (data/Keep.json, KeepComponent.json, KeepPosition.json,
-- KeepHookPoint.json). Do NOT edit by hand — rerun the generator instead.
--
-- The OpenDAoC-Database upstream ships frontier keeps in regions 1/100/200
-- (Old Frontiers) and an empty keepcomponent table. KeepManager in this
-- fork targets region 163 (New Frontiers — see DEFAULT_FRONTIERS_REGION),
-- so without this patch the frontier loads as terrain only: no keeps, no
-- towers, no visible structures, and the realm-master teleporters drop the
-- player in an empty Old Frontier instead of NF.
--
-- This patch is idempotent (REPLACE INTO + UPDATE) and applied by the
-- gameserver entrypoint on every container start, the same way as
-- heretic_live.sql and battlegrounds_live.sql.
-- =====================================================================
SET FOREIGN_KEY_CHECKS = 0;

-- ---- Region frontier flags ----------------------------------------
-- Without these flips, KeepManager.Load reads IsFrontier from the DB
-- and builds m_frontierRegionsList = {1, 100, 200} (the upstream OF
-- defaults), excluding 163. GetKeepsByRealmMap then silently filters
-- out every NF keep -> the warmap has no colored ownership markers
-- and the realm-master 'teleport to keep' path refuses to fire.
-- Apply BEFORE inserting keeps so the manager builds the right list
-- at first boot (and idempotent on re-boots).

UPDATE `regions` SET IsFrontier = 1 WHERE RegionID = 163;
UPDATE `regions` SET IsFrontier = 0 WHERE RegionID IN (1, 100, 200);

-- ---- NF main keeps (21) + NF towers (84) --------------------------
-- Sourced from Eve-of-Darkness Keep.json, region 163.


-- ---- Relic keeps (6) — moved from OF to NF -------------------------
-- Coordinates are approximate (no canonical NF relic-keep coords in
-- the EoD vanilla dump). Placed inside the canonical NF relic zone
-- for each realm. Adjust in-place if you want pixel-perfect retail
-- positioning — the keeps will work either way.

UPDATE `keep` SET Region = 163, X = 590000, Y = 590000, Z = 8500, Heading = 1920
 WHERE KeepID = 57;
UPDATE `keep` SET Region = 163, X = 605000, Y = 605000, Z = 8500, Heading = 3645
 WHERE KeepID = 58;
UPDATE `keep` SET Region = 163, X = 680000, Y = 380000, Z = 8500, Heading = 2977
 WHERE KeepID = 82;
UPDATE `keep` SET Region = 163, X = 700000, Y = 410000, Z = 8500, Heading = 470
 WHERE KeepID = 198;
UPDATE `keep` SET Region = 163, X = 460000, Y = 640000, Z = 8500, Heading = 2474
 WHERE KeepID = 110;
UPDATE `keep` SET Region = 163, X = 455000, Y = 660000, Z = 8500, Heading = 3925
 WHERE KeepID = 111;

-- ---- Keep components (~960 rows for NF main keeps + towers) -------
-- Both Skin<20 (OF appearance) and Skin>20 (NF appearance) variants
-- are included. KeepManager filters by USE_NEW_KEEPS at load time.



-- ---- Keep hook-point templates (skin-keyed, region-independent) ----
-- Required so the keep manager can place guards / doors on every skin.



-- ---- Keep position templates (guard / door spawns per skin) ---------


-- ---- NF doors ----------------------------------------------------
-- 30 NF-zone doors (Agramon central + Mid/Hib/Alb frontier zones).
-- Upstream ships only 18 of these; the 12 Agramon (zone 163) grille
-- doors are missing and the 'porte grilles' between realms simply
-- don't open in-game. Source: Eve-of-Darkness vanilla Door.json.


-- ---- Border-keep teleport destinations → NF region 163 -------------
-- Coords match KeepManager.GetBorderKeepLocation. Without this UPDATE
-- the realm-master 'Castle Sauvage' / 'Snowdonia' / ... destinations
-- still point to the now-empty Old Frontier regions 1/100/200.

UPDATE `teleport` SET RegionID = 163, X = 653811, Y = 616998, Z = 9560, Heading = 2040
 WHERE TeleportID = 'Castle Sauvage' AND Realm = 1;
UPDATE `teleport` SET RegionID = 163, X = 616149, Y = 679042, Z = 9560, Heading = 1611
 WHERE TeleportID = 'Snowdonia Fortress' AND Realm = 1;
UPDATE `teleport` SET RegionID = 163, X = 651460, Y = 313758, Z = 9432, Heading = 1004
 WHERE TeleportID = 'Svasud Faste' AND Realm = 2;
UPDATE `teleport` SET RegionID = 163, X = 715179, Y = 365101, Z = 9432, Heading = 314
 WHERE TeleportID = 'Vindsaul Faste' AND Realm = 2;
UPDATE `teleport` SET RegionID = 163, X = 396519, Y = 618017, Z = 9838, Heading = 2159
 WHERE TeleportID = 'Druim Ligen' AND Realm = 3;
UPDATE `teleport` SET RegionID = 163, X = 432841, Y = 680032, Z = 9747, Heading = 2585
 WHERE TeleportID = 'Druim Cain' AND Realm = 3;


-- ---- Server property: USE_NEW_KEEPS = 1 (NF appearance) -----------
-- KeepManager.Load filters keep components by Skin: <20 for OF look,
-- >20 for NF look. The default upstream is 0; flip it so the freshly
-- inserted NF rows render with the NF appearance set.
UPDATE `serverproperty` SET Value = '1'
 WHERE `Key` = 'use_new_keeps' AND Value = '0';

SET FOREIGN_KEY_CHECKS = 1;
-- =====================================================================
-- End nf_live.sql
-- =====================================================================
